import manifest from "../../../assets/textures/decorations/verge-foliage-atlas.json";
import { createFoliageTileLookup, type FoliageAtlasManifest, type FoliageCardVertices,
  foliageCardVertices } from "../plants/foliage-atlas-layout";
import type { VergeFoliageTileId } from "./verge-foliage-atlas-layout";

/** Generated by `npm run verge-foliage-atlas`; pure data, safe for workers and recipes. */
export const VERGE_FOLIAGE_ATLAS = manifest as unknown as FoliageAtlasManifest<VergeFoliageTileId>;

export const getVergeFoliageTile = createFoliageTileLookup(VERGE_FOLIAGE_ATLAS);

export const vergeFoliageCardVertices = (id: VergeFoliageTileId): FoliageCardVertices =>
  foliageCardVertices(getVergeFoliageTile(id));
